import{_ as l,o as i,c as t,a4 as a}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-119","description":"","frontmatter":{"date":"2021-04-10T14:42:32","title":"写作课作业-119","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/119.md","filePath":"posts/homework/119.md"}'),o={name:"posts/homework/119.md"};function r(p,e,s,n,_,c){return i(),t("div",null,[...e[0]||(e[0]=[a('<blockquote><p>《一年顶十年》之《贵人 如何让自己拥有超好的贵人运》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li>走出去，你才更有可能遇到贵人。</li><li>付费是一种极为简单有效的连接方式。</li><li>愿意给你付费的人，比一般人更认可你，也更愿意帮助你。</li><li>你要做一个持续付出的人，付出越多，肯帮你的人也会越多。</li><li>如果别人帮过你，你要表示感谢，更要记在心上，并想办法在合适的时候，给对方回馈。</li><li>我们要持续成长，成长为一个对别人有价值的人。</li><li>靠谱，最起码是在结果上做到符合他人的预期。如果要让人觉得你特别靠谱，你还要学会给惊喜，在结果上做到超预期。</li><li>大量请人吃“学习饭”，用吃饭时间交朋友，还能互相学习，一举两得。</li><li>汇报，也是一种回报。</li><li>被重视、被鼓励、被夸奖、被理解、被支持、被需要、是你的刚需，也是别人的刚需。</li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>在还不能为别人提供价值的时候，先学会鼓励人。</p><p>汇报也是一种回报，这一点如果不是看书，其实很难理解其中的逻辑，默默成长并正确的表现自己。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',13)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
